"""Round 3, B10: P-256's fixed-base table, T[i][j-1] = j * 32^i * G for
i in 0..52, j in 1..=16 (signed 5-bit digits; gen_gtable4.py and
gen_gtable5u.py made the unsigned 4- and 5-bit ones), as affine (x, y) in p256's internal form (Montgomery, R = 2^256,
eight little-endian u32 words). Exact Python
integers; the table is checked by the Rust tests against the generic
multiply."""
p = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
a = p - 3
b = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
Gx = 0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296
Gy = 0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5
n = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
assert (Gy * Gy - (Gx ** 3 + a * Gx + b)) % p == 0


def add(P, Q):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2:
        if (y1 + y2) % p == 0:
            return None
        lam = (3 * x1 * x1 + a) * pow(2 * y1, -1, p) % p
    else:
        lam = (y2 - y1) * pow(x2 - x1, -1, p) % p
    x3 = (lam * lam - x1 - x2) % p
    return (x3, (lam * (x1 - x3) - y1) % p)


R = 1 << 256


def mont_hex(v):
    return f'{v * R % p:064x}'


rows = []
base = (Gx, Gy)  # 2^(W i) * G
W = 5
for i in range((256 + W - 1) // W):
    row = []
    acc = None
    for j in range(1, (1 << (W - 1)) + 1):
        acc = add(acc, base)
        row.append(acc)
    rows.append(row)
    # next base: 2^W * base
    nb = None
    for _ in range(1 << W):
        nb = add(nb, base)
    base = nb

out = ['//! P-256\'s fixed-base table (round 3, generated by `gen_gtable.py` with',
       '//! exact integers): entry `[i][j - 1]` is `j * 32^i * G`, affine, in this',
       '//! crate\'s internal form (Montgomery, R = 2^256, little-endian words).',
       '//! `primeorder`\'s comb multiplies the generator by one constant-time',
       '//! lookup and one mixed addition a signed 5-bit digit, no doublings; the tests hold',
       '//! it to the generic multiply.',
       '',
       'use super::field::FieldElement;',
       'use crate::{NistP256, U256};',
       'use primeorder::GeneratorTable;',
       '',
       'const fn fe(h: &str) -> FieldElement {',
       '    FieldElement(U256::from_be_hex(h))',
       '}',
       '',
       'pub(crate) static GENERATOR_TABLE: GeneratorTable<NistP256> = [']
for row in rows:
    out.append('    [')
    for (x, y) in row:
        out += ['        (', f'            fe("{mont_hex(x)}"),', f'            fe("{mont_hex(y)}"),', '        ),']
    out.append('    ],')
out.append('];')
import os
import sys
dst = sys.argv[1] if len(sys.argv) > 1 else 'F:/coding/janus/rusty_esp_mid/vendor/p256/src/arithmetic/generator_table.rs'
# never open(dst, 'w') on F: (a truncation there once lost a file)
open(dst + '.tmp', 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
os.replace(dst + '.tmp', dst)
print('rows', len(rows), 'entries', sum(len(r) for r in rows))
